import{_ as a,o,c,a3 as i}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"什么是 xclang？","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"什么是 xclang？ | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/guide/what-is-xclang"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/guide/what-is-xclang"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/guide/what-is-xclang"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/guide/what-is-xclang"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/guide/what-is-xclang"}]]},"headers":[],"relativePath":"zh/xclang/guide/what-is-xclang.md","filePath":"zh/xclang/guide/what-is-xclang.md","lastUpdated":1794509097000}'),r={name:"zh/xclang/guide/what-is-xclang.md"};function l(n,e,t,s,d,g){return o(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="什么是-xclang" tabindex="-1">什么是 xclang？ <a class="header-anchor" href="#什么是-xclang" aria-label="Permalink to &quot;什么是 xclang？&quot;">​</a></h1><p>xclang 是一套用于交叉编译的 clang 工具链：一个编译器面向所有目标平台。单个目录里包含编译器、链接器、二进制工具，以及八个目标平台的 <em>sysroot</em>（C 标准库的头文件与库文件）和预编译运行时库。交叉编译只需传一个 <code>--target</code> 参数：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-w64-mingw32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.exe</span></span></code></pre></div><h2 id="版本包含的内容" tabindex="-1">版本包含的内容 <a class="header-anchor" href="#版本包含的内容" aria-label="Permalink to &quot;版本包含的内容&quot;">​</a></h2><ul><li><strong>clang、lld 与 LLVM 二进制工具</strong>：基于上游 LLVM 加上少量正在合入上游的<a href="./../reference/patches">补丁</a>构建，打包为单个多合一可执行文件（<code>llvm</code>），并针对六个主机平台静态链接 xclang 自身的 <code>libc++</code>（<a href="./../design/toolchain">工具链结构</a>）。</li><li><strong>每个压缩包内置八个目标平台</strong>：<a href="./cross-compiling#linux">Linux</a> x64 与 arm64（glibc 2.17，以及用于静态程序的 musl 1.2.6）、<a href="./cross-compiling#windows">Windows</a> x64 与 arm64（使用 UCRT 的 MinGW-w64）、<a href="./cross-compiling#macos">macOS</a> arm64 与 x64。每个目标平台都带有预编译好的 sysroot、<code>libc++</code>、<code>libc++abi</code>、<code>libunwind</code> 和 <code>compiler-rt</code>，以及将 <code>clang</code> 指向这些目录的配置文件（<a href="./cross-compiling">交叉编译</a>）。</li><li><strong>MSVC 目标平台</strong>：Windows x64 与 arm64，使用微软的 CRT 和 xclang 的 <code>libc++</code>（或微软的 STL），可在任意主机上编译，配合 <code>xclang</code> 命令从微软获取的 SDK 或 Windows 本机安装的 Visual Studio 使用（<a href="./cross-compiling#windows">Windows</a>、<a href="./../design/windows">Windows 设计</a>）。</li><li><strong><code>xclang</code> 命令</strong>：用于获取不允许二次分发的 Apple 与微软 SDK；<code>xclang cargo</code> 则无需编写任何 cargo 配置即可为 xclang 的目标平台构建 Rust 代码（<a href="./../reference/xclang-command"><code>xclang</code> 命令</a>、<a href="./../integrations/cargo">Rust 与 Cargo</a>）。</li><li><strong>CMake 包与 Bazel 模块</strong>：可用于主机或任意目标平台，并随构建过程按需编译 <code>import std</code>（<a href="./../integrations/cmake">CMake</a>、<a href="./../integrations/bazel">Bazel</a>）。</li><li><strong>运行时库源码</strong>：供 CMake 包与 Bazel 模块在启用 MemorySanitizer 或调整 <code>libc++</code> 加固（hardening）及 ABI 选项时按需编译，支持除 MSVC 以外的所有目标平台（<a href="./../features/runtimes-from-source">从源码构建运行时库</a>）。</li><li><strong>libclang</strong>：构建这个版本所用的 <code>clang</code> 与 LLVM 静态库及头文件，供基于 <code>clang</code> 开发的工具使用（<a href="./../features/libclang">libclang</a>）。</li></ul><p>尚未发布的其他目标平台与功能见<a href="./../design/roadmap">路线图</a>。</p><h2 id="它对构建的作用" tabindex="-1">它对构建的作用 <a class="header-anchor" href="#它对构建的作用" aria-label="Permalink to &quot;它对构建的作用&quot;">​</a></h2><p>当 C++ 构建的产物只取决于声明的输入时，这样的构建就是<em>封闭的</em>（hermetic）：在任何机器、任何目录下，同样的源码和工具链都会产出同样的程序。这正是 xclang 的设计目标。</p><ul><li><strong>可复现。</strong> 已发布的版本不会覆盖替换，重新构建会发布为下一个修订号。Bazel 模块与 CMake 下载都会校验每个压缩包的 <code>sha256</code>。在 Bazel 构建中，除 Xcode 的 macOS SDK 外，命令行与调试信息都不含绝对路径，在另一个代码检出目录中构建也能产出逐字节相同的结果（<a href="./../design/bazel-module">Bazel 模块</a>）。</li><li><strong>产物可移植。</strong> 编译出的程序在运行时只依赖目标操作系统必定自带的系统库：<a href="./cross-compiling#linux">Linux</a> 上是 glibc 2.17 及以上（使用 musl 时则无任何依赖），<a href="./cross-compiling#windows">Windows 10</a> 及以上，或 <a href="./cross-compiling#macos">macOS 13</a> 及以上。<code>libc++</code> 与其他运行时库均已静态链接进程序，而且面向 GCC 编写的构建脚本（<code>-latomic</code>、<code>-lgcc_s</code>、<code>-lstdc++</code>）无需修改即可链接（<a href="./../design/hermeticity">封闭性</a>）。</li><li><strong>一个编译器面向所有目标平台。</strong> <code>clang</code> 本身支持编译所有 LLVM 目标平台，而 xclang 随附了各目标平台的库文件。切换目标平台只需传入 <code>--target=&lt;triple&gt;</code>，升级一次编译器即可同时更新所有目标平台（<a href="./cross-compiling">交叉编译</a>）。</li><li><strong>准确的构建缓存。</strong> 直接使用宿主机上的编译器时，升级编译器后构建缓存仍可能返回旧版本编译出的目标文件。在 Bazel 中，构建动作读取的每个工具链文件都是显式声明的输入，升级版本后会准确重编受影响的目标，模块文件也会作为 import 它的文件的输入参与缓存计算（<a href="./../design/bazel-module">Bazel 模块</a>、<a href="./../features/modules">C++20 模块</a>）。</li><li><strong>C++20 模块。</strong> 模块文件只能被采用相同语言选项编译的源码 import，因此无法预编译分发 <code>std</code> 模块。xclang 会按当前构建的编译选项现场编译 <code>libc++</code> 的 <code>std</code> 与 <code>std.compat</code> 模块：在 CMake 中无需开启实验性开关即可使用 <code>xclang::std</code>，在 Bazel 中则是 <code>@xclang//bazel:std</code>（<a href="./../features/modules">C++20 模块</a>）。</li><li><strong>速度快。</strong> 每个主机上的 <code>clang</code> 与 <code>lld</code> 均开启 PGO 和 ThinLTO 构建，训练负载涵盖真实 C/C++ 代码编译、预编译头、C++20 模块与代码补全（<a href="./../design/pgo">PGO</a>）。<code>libclang</code> 以 ThinLTO bitcode 形式分发，配合 ThinLTO 缓存可将基于它构建的工具的重新链接时间缩短到几秒（<a href="./../features/libclang">libclang</a>）。</li><li><strong>正确性检查与调试工具。</strong> xclang 随附各 sanitizer 的运行时库以及带 ASan 插桩的 <code>libc++</code>，避免容器溢出的误报（<a href="./../features/sanitizers">sanitizer</a>），并支持为 MemorySanitizer 从源码编译运行时库（<a href="./../features/runtimes-from-source">从源码构建运行时库</a>）。调试符号可与程序分离：除 MSVC 目标生成 PDB 外，所有目标均可生成每次构建完全一致的 GSYM 文件，macOS 目标还可生成 dSYM（<a href="./../features/debugging">调试</a>）。</li><li><strong>供应链可追溯。</strong> 每个压缩包都记录在 <code>SHA256SUMS</code> 中，基于 LLVM 官方源码包与公开记录的<a href="./../reference/patches">补丁</a>构建，在两台机器上各打包一次并逐字节比对，同时随包附带各组件的许可证与 SPDX 文档（<a href="./../reference/releases">版本发布</a>、<a href="./../reference/layout">压缩包目录结构</a>）。厂商 SDK 不会打包进压缩包，而是由用户直接从厂商下载，并锁定版本与 <code>sha256</code>（<a href="./../reference/xclang-command"><code>xclang</code> 命令</a>）。</li><li><strong>一套工具链通用于各种构建方式。</strong> 同一个工具链目录既可用于<a href="./../integrations/clang">直接调用 clang、Make 与 Meson</a>，也可用于 <a href="./../integrations/cmake">CMake</a>、<a href="./../integrations/bazel">Bazel</a> 和 <a href="./../integrations/cargo">cargo</a>，无论它来自 pixi、压缩包、FetchContent 还是 Bazel registry（<a href="./quick-start">快速开始</a>）。</li></ul><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>向用户机器分发程序的项目</strong>：命令行工具、语言服务器和构建工具，无需用户安装运行库安装包或 Homebrew，单文件即可运行。</li><li><strong>为多个目标平台构建的 CI</strong>：在单一 runner 操作系统上用同一个编译器版本构建所有目标平台（<a href="./../integrations/ci">CI</a>）。</li><li><strong>在开发机与 CI 上锁定同一套工具链的团队</strong>：统一用于 CMake、Bazel 和直接命令行调用。</li><li><strong>使用 <code>import std</code> 的 C++20 模块项目</strong>：支持 CMake 与 Bazel。</li><li><strong>基于 clang 的工具</strong>：链接开启 PGO 构建的 <code>libclang</code>。</li></ul><p>xclang 是为 <a href="https://github.com/clice-io/clice" target="_blank" rel="noreferrer">clice</a> 开发的，clice 的发布构建是它的第一个用户。<a href="https://github.com/clice-io/catter" target="_blank" rel="noreferrer">catter</a> 同样使用它构建。xclang 的 CI 在 Linux 上将 <a href="https://github.com/clice-io/kotatsu" target="_blank" rel="noreferrer">kotatsu</a> 的测试交叉编译到 Windows，并在 Windows 上运行。</p><h2 id="它不是什么" tabindex="-1">它不是什么 <a class="header-anchor" href="#它不是什么" aria-label="Permalink to &quot;它不是什么&quot;">​</a></h2><ul><li><strong>其他工具链编译的 C++ 库需要配套的 C++ 标准库。</strong> xclang 默认使用 <code>libc++</code> 并静态链接进每个程序，而用 GCC 的 <code>libstdc++</code> 或微软的 STL 编译出的 C++ 库具有不同的 ABI。请用 xclang 为目标平台重新编译 C++ 依赖库，或者传入 <code>-stdlib=platform</code> 改用平台的 C++ 标准库并放弃单文件自包含产物（<a href="./cross-compiling#the-platform-s-c-library">交叉编译</a>）。C 语言库不受影响。</li><li><strong>每个共享库各自持有一份 <code>libc++</code>。</strong> 每个共享库都链接了独立的 <code>libc++</code>，因此不应跨共享库边界传递 C++ 对象；在 Linux 与 macOS 上，一个共享库抛出的标准异常在另一个共享库中只能被 <code>catch (...)</code> 捕获（<a href="./../design/hermeticity#one-libc-per-shared-object">封闭性</a>、<a href="./../design/roadmap#shared-runtime">路线图</a>）。</li><li><strong>不含 OpenMP 运行时库，也不含 <code>clang-format</code>、<code>clang-tidy</code> 或 <code>clangd</code> 可执行文件。</strong> xclang 是一套编译器工具链（<a href="./../design/roadmap#openmp">OpenMP</a>、<a href="./../design/roadmap#tool-binaries">工具可执行文件</a>）。</li><li><strong>不用于构建 conda-forge 软件包。</strong> 构建 conda-forge 包请使用 conda-forge 自己的编译器，它们会通过 <code>run_exports</code> 链接共享运行时库包；xclang 不这么做（<a href="./../design/roadmap#conda-forge">路线图</a>）。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./quick-start">快速开始</a>：安装 xclang，为各个目标平台构建程序，再构建一个使用 <code>import std</code> 的 CMake 项目。</li><li><a href="./cross-compiling">交叉编译</a>：目标平台、厂商 SDK 与各平台细节。</li><li><a href="./../reference/releases">版本发布</a>：版本标签、分发渠道、发布文件与下载校验。</li></ul>',16)])])}const f=a(r,[["render",l]]);export{p as __pageData,f as default};
